import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Map<String, String> vazifa = new HashMap<>();
        vazifa.put("sign", "deter");
        vazifa.put("lighting", "deter");
        vazifa.put("guard", "deter");
        vazifa.put("wall", "delay");
        vazifa.put("lock", "delay");
        vazifa.put("turnstile", "delay");
        vazifa.put("mantrap", "delay");
        vazifa.put("sensor", "detect");
        vazifa.put("cctv", "detect");
        vazifa.put("alarm", "detect");
        vazifa.put("patrol", "respond");
        vazifa.put("police", "respond");
        String[] tartib = {"deter", "delay", "detect", "respond"};
        Map<String, Integer> son = new HashMap<>();
        for (String turi : tartib) son.put(turi, 0);
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        for (int j = 0; j < n; j++) {
            in.nextLine();
            son.put("detect", son.get("detect") + 1);
        }
        for (String turi : tartib) System.out.println(turi + " " + son.get(turi));
    }
}

